/* A field desk for researched living culture. Symbol drawings are original
   editorial graphics, never photographs or reconstructions of listed venues. */
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const categories={graffiti:'Graffiti / paměť',artshop:'Graffiti shopy',hiphop:'Hip-hop / kluby',recordshop:'Desky / digging',philosophy:'Filozofie / dialog'};
const steps=[['observe','Všímej si'],['try','Vytvoř'],['review','Zpětná vazba'],['output','Tvůj výstup']];
let sequence=0;
const safeUrl=value=>{try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password?url.href:null;}catch{return null;}};
function validPlace(place){return place&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(place.id)&&Object.hasOwn(categories,place.category)&&['name','address','access','checkedAt'].every(key=>typeof place[key]==='string'&&place[key].trim())&&Array.isArray(place.facts)&&place.facts.length&&place.facts.every(value=>typeof value==='string')&&Array.isArray(place.sources)&&place.sources.some(source=>source&&safeUrl(source.url))&&place.task&&['question',...steps.map(([key])=>key)].every(key=>typeof place.task[key]==='string'&&place.task[key].trim());}
function symbol(category){
 const ring='<g class="cb-orbit"><circle cx="240" cy="205" r="171"/><path d="M240 18v30M240 362v30M52 205h30M398 205h30M110 74l22 22M348 316l22 22M109 337l23-23M347 95l23-23"/></g>';
 const graffiti='<g class="cb-ink"><path class="cb-solid" d="m94 256 63-131 47 16-49 79 59-21-25 59-61 32ZM189 283l49-170 48 10-25 57 54-24-17 56-56 20-11 43ZM292 263l35-110 41 17-13 37 34-10-18 53-52 33Z"/><path d="m107 253 44-91 20 7M205 269l35-122 20 5M306 251l20-65M149 233l36-13M260 201l29-13M348 229l21-7"/><path class="cb-run" pathLength="1" d="M76 306q153-72 329-7M106 319l252 10"/></g><g class="cb-star"><path d="m360 64 8 22 25-2-20 16 7 24-21-14-21 15 7-25-21-16 26 2Z"/></g><path d="M97 283v39m9-31v53M298 285v41"/>';
 const shop='<g class="cb-ink"><path class="cb-solid" d="m94 176 88-27 32 157-87 27Z"/><path d="m92 175 5-29 70-21 15 24M119 137l-4-23 39-12 8 23M142 116l-5-21 11-4 7 21M111 202l70-22M128 279l58-18"/><path class="cb-run" pathLength="1" d="m151 230 10-17 15 8-9 19-16 4-5-11ZM141 305l36-11"/><path class="cb-solid" d="m237 158 116 19-29 158-116-20Z"/><path d="m247 170-25 133 90 16M263 194l58 10M256 217l43 7M249 239l54 9M244 267l42 7M327 164l26-85 23 7-26 85-14 18Z"/></g><g class="cb-star"><path d="m237 66 5 22 23 5-23 5-5 23-5-23-23-5 23-5Z"/></g>';
 const hiphop='<g class="cb-ink"><path class="cb-solid" d="M90 144h110v188H90ZM280 163h104v169H280Z"/><circle class="cb-speaker" cx="145" cy="265" r="38"/><circle cx="145" cy="265" r="16"/><circle class="cb-speaker" cx="332" cy="274" r="34"/><circle cx="332" cy="274" r="12"/><circle cx="145" cy="184" r="17"/><circle cx="332" cy="201" r="14"/><g transform="rotate(18 240 175)"><rect class="cb-paper" x="222" y="93" width="40" height="90" rx="19"/><path d="M229 111h25M226 125h32M226 140h32M229 155h25M230 183v84h24v-84"/></g><path class="cb-run" pathLength="1" d="M262 267q38 65-26 77t-11 43"/></g><g class="cb-wave"><path d="M177 92q-22 28-10 53M163 76q-32 39-18 73M300 94q23 29 8 55M314 78q32 40 16 77"/></g>';
 const record='<g class="cb-ink"><path class="cb-solid" d="m77 143 309-27 21 220-309 22Z"/><path d="m88 155 286-25 18 192-284 21Z"/><g class="cb-vinyl"><circle class="cb-dark" cx="224" cy="235" r="90"/><circle cx="224" cy="235" r="75"/><circle cx="224" cy="235" r="64"/><circle cx="224" cy="235" r="54"/><circle class="cb-solid" cx="224" cy="235" r="33"/><path class="cb-dark" d="m215 220 27 14-25 17Z"/><path d="M164 184a78 78 0 0 1 84-24M256 301a75 75 0 0 0 31-39"/></g><path class="cb-paper" d="m340 156 11-1 7 102-41 44-11-10 39-42Z"/><circle cx="343" cy="151" r="13"/><path d="m121 309 36-4m-34 15 36-4"/></g><g class="cb-star"><path d="m175 62 6 22 23 6-23 6-6 22-6-22-23-6 23-6Z"/></g>';
 const philosophy='<g class="cb-ink"><path class="cb-solid" d="m91 208 150-92 151 92-151 91Z"/><path class="cb-dark" d="M105 208q135-136 272 0-136 134-272 0Z"/><g class="cb-eye"><circle class="cb-paper" cx="241" cy="208" r="48"/><circle class="cb-solid" cx="241" cy="208" r="31"/><circle class="cb-dark" cx="241" cy="208" r="14"/><path d="M241 161v17m0 61v17M195 208h17m58 0h17M208 175l12 12m43 43 12 12m-67 0 12-12m43-43 12-12"/></g><path class="cb-run" pathLength="1" d="M241 108V65h82V37M241 308v51h-86v24M115 157l-36-30V83M365 259l38 31v64"/><circle cx="323" cy="37" r="8"/><circle cx="155" cy="383" r="8"/><circle cx="79" cy="83" r="8"/><circle cx="403" cy="354" r="8"/></g>';
 return `<svg class="cb-symbol" viewBox="0 0 480 410" aria-hidden="true" focusable="false">${ring}${({graffiti,artshop:shop,hiphop,recordshop:record,philosophy})[category]}</svg>`;
}

export function cultureSymbolMarkup(category){return symbol(Object.hasOwn(categories,category)?category:'graffiti');}

/* Optional illustrations in existing atlas previews/profiles. No separate image
   requests, no permanent JS animation loop, and no ownership of caller content. */
export function mountCultureSymbols(scope=document){
 const doc=scope?.ownerDocument||scope,win=doc?.defaultView;
 if(!scope?.querySelectorAll||!win)return {rescan(){},destroy(){}};
 const selector='.culture-profile-symbol[data-culture-symbol]',items=new Map(),visible=new Set(),listeners=[];
 const reduced=win.matchMedia?.('(prefers-reduced-motion: reduce)');let disposed=false,queued=false,io,mo;
 const listen=(target,type,handler)=>{target.addEventListener(type,handler);listeners.push(()=>target.removeEventListener(type,handler));};
 const allowed=()=>!disposed&&!doc.hidden&&!reduced?.matches&&doc.documentElement.dataset.motion!=='off'&&!['off','reduced','quiet','calm'].includes(doc.documentElement.dataset.selfmadeMotion)&&!doc.body.classList.contains('simple-mode');
 function refresh(){const modal=doc.querySelector('dialog[open]');for(const item of items.values()){const available=item.host.isConnected&&!item.host.closest('[hidden],[inert],dialog:not([open])')&&(!modal||modal.contains(item.host));item.host.classList.toggle('cb-animating',allowed()&&available&&visible.has(item.host));}}
 function remove(item){io?.unobserve(item.host);visible.delete(item.host);item.svg?.remove();item.host.classList.remove('cb-animating');items.delete(item.host);}
 function scan(){queued=false;if(disposed)return;for(const item of items.values())if(!item.host.isConnected||item.host.dataset.cultureSymbol!==item.category||!item.host.contains(item.svg))remove(item);const hosts=[...(scope.matches?.(selector)?[scope]:[]),...scope.querySelectorAll(selector)];for(const host of hosts){if(items.has(host)||!Object.hasOwn(categories,host.dataset.cultureSymbol))continue;host.insertAdjacentHTML('afterbegin',cultureSymbolMarkup(host.dataset.cultureSymbol));const svg=host.querySelector('.cb-symbol');const item={host,svg,category:host.dataset.cultureSymbol};items.set(host,item);io?.observe(host);}refresh();}
 function queue(){if(!queued&&!disposed){queued=true;Promise.resolve().then(scan);}}
 if(win.IntersectionObserver){io=new win.IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)visible.add(entry.target);else visible.delete(entry.target);}refresh();},{threshold:.03});}
 if(win.MutationObserver){mo=new win.MutationObserver(records=>{if(records.some(record=>record.type==='childList'&&[...record.addedNodes,...record.removedNodes].some(node=>node.nodeType===1&&(node.matches?.(selector)||node.querySelector?.(selector)))))queue();if(records.some(record=>record.type==='attributes'&&((record.target===doc.documentElement&&['data-motion','data-selfmade-motion'].includes(record.attributeName))||(record.target===doc.body&&record.attributeName==='class')||['open','hidden','inert','data-culture-symbol'].includes(record.attributeName))))queue();});mo.observe(doc.documentElement,{attributes:true,attributeFilter:['data-motion','data-selfmade-motion']});mo.observe(doc.body,{childList:true,subtree:true,attributes:true,attributeFilter:['open','hidden','inert','data-culture-symbol','class']});}
 listen(doc,'visibilitychange',refresh);if(reduced?.addEventListener)listen(reduced,'change',refresh);
 scan();return {rescan:scan,destroy(){if(disposed)return;disposed=true;io?.disconnect();mo?.disconnect();listeners.forEach(remove=>remove());for(const item of [...items.values()])remove(item);visible.clear();}};
}

export function mountCultureBoard(host,{places=[],onOpen=()=>{},onFilter=()=>{},read=()=>({}),write=()=>false,notify=()=>{}}={}){
 if(!host?.replaceChildren)return {destroy(){}};
 const unique=new Set();const items=Array.isArray(places)?places.filter(place=>{if(!validPlace(place)||unique.has(place.id))return false;unique.add(place.id);return true;}):[];
 if(!items.length){host.innerHTML='<p class="cb-empty">Kulturní terénní průvodce se nepodařilo načíst. Původní atlas a jeho ověřené zdroje zůstávají dostupné.</p>';return {destroy(){host.replaceChildren();}};}
 const doc=host.ownerDocument,win=doc.defaultView,uid=`culture-${++sequence}`;
 let selected=items[0].id,filter='all',step=0,field=false,disposed=false,visible=false,raf=0;
 const drafts=new Map(),listeners=[],reduced=win.matchMedia?.('(prefers-reduced-motion: reduce)');
 const listen=(target,type,handler,options)=>{target.addEventListener(type,handler,options);listeners.push(()=>target.removeEventListener(type,handler,options));};
 const getPlace=()=>items.find(place=>place.id===selected);
 const filtered=()=>items.filter(place=>filter==='all'||place.category===filter);
 function storedNotes(){try{const value=read('atlas-observations',{});return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {};}}
 function capture(){const input=host.querySelector('[data-cb-note]');if(input)drafts.set(selected,input.value);}
 function allowed(){return !disposed&&visible&&!doc.hidden&&!reduced?.matches&&doc.documentElement.dataset.motion!=='off'&&!['off','reduced','quiet','calm'].includes(doc.documentElement.dataset.selfmadeMotion)&&!doc.body.classList.contains('simple-mode')&&!doc.querySelector('dialog[open]');}
 function refreshMotion(){host.classList.toggle('cb-animating',allowed());}
 function render(){
  const place=getPlace(),view=filtered(),index=view.findIndex(item=>item.id===selected),note=drafts.has(selected)?drafts.get(selected):storedNotes()[selected];
  const nav=new URLSearchParams({api:'1',query:`${place.name}, ${place.address}`});
  const expedition=['writer','mc','dj','knowledge'].includes(place.relatedExpedition)?place.relatedExpedition:'knowledge';
  const sourceLinks=place.sources.filter(source=>source&&safeUrl(source.url)).map(source=>`<li><a href="${escape(safeUrl(source.url))}" target="_blank" rel="noopener">${escape(source.title||'Oficiální zdroj')} ↗</a></li>`).join('');
  host.classList.add('culture-board');host.classList.toggle('cb-field',field);
  host.innerHTML=`<header class="cb-heading"><div><p class="cb-kicker">PARIS / ŽIVÁ KULTURA / TVOJE VLASTNÍ CESTA</p><h3>STREET.<br>SOUND. <span>THOUGHT.</span></h3></div><div class="cb-intro"><p>Město netvoří jen památky. Najdi lidi, zvuk a myšlenku. Pak vytvoř něco vlastního.</p><button type="button" class="cb-field-toggle" data-cb-field aria-pressed="${field}">${field?'Zobrazit příběh':'Terénní režim'} ↗</button></div></header><div class="cb-filters" role="group" aria-label="Kulturní vrstvy"><button type="button" data-cb-filter="all" aria-pressed="${filter==='all'}">Vše / ${items.length}</button>${Object.entries(categories).filter(([key])=>items.some(item=>item.category===key)).map(([key,label])=>`<button type="button" data-cb-filter="${key}" aria-pressed="${filter===key}">${label}</button>`).join('')}</div><div class="cb-layout"><aside class="cb-directory" aria-label="Kulturní zastávky"><p class="cb-label">VYBER SI VLASTNÍ VLÁKNO</p><div class="cb-place-list">${view.map((item,i)=>`<button type="button" data-cb-place="${escape(item.id)}" aria-pressed="${item.id===selected}"><span>${String(i+1).padStart(2,'0')}</span><strong>${escape(item.name)}</strong><small>${escape(categories[item.category])}</small></button>`).join('')}</div><div class="cb-symbol-stage" data-cb-art="${place.category}">${symbol(place.category)}<span>CAISIK / AUTORSKÝ SYMBOL</span></div><p class="cb-art-note">Výtvarný symbol kulturní vrstvy. Nejde o fotografii ani model uvedeného místa.</p></aside><article class="cb-quest" aria-labelledby="${uid}-title"><div class="cb-quest-top"><p class="cb-label">${escape(categories[place.category])} / ${String(index+1).padStart(2,'0')} Z ${view.length}</p><div class="cb-sequence"><button type="button" data-cb-prev aria-label="Předchozí kulturní zastávka" ${view.length<2?'disabled':''}>←</button><button type="button" data-cb-next aria-label="Další kulturní zastávka" ${view.length<2?'disabled':''}>→</button></div></div><h4 id="${uid}-title" tabindex="-1">${escape(place.name)}</h4><div class="cb-field-address"><p class="cb-address">⌖ ${escape(place.address)}</p><a href="https://www.google.com/maps/search/?${escape(nav)}" target="_blank" rel="noopener">Navigovat na adresu ↗</a><p class="cb-access">${escape(place.access)}</p></div><div class="cb-context"><p class="cb-label">DOLOŽENÝ KONTEXT</p><ul>${place.facts.map(fact=>`<li>${escape(fact)}</li>`).join('')}</ul></div><div class="cb-practice"><p class="cb-label">TVŮRČÍ ZADÁNÍ / CAISIK</p><p class="cb-question">${escape(place.task.question)}</p><div class="cb-steps" role="group" aria-label="Kroky vlastní praxe">${steps.map(([key,label],i)=>`<button type="button" data-cb-step="${i}" aria-pressed="${i===step}" aria-controls="${uid}-practice">${String(i+1).padStart(2,'0')} / ${label}</button>`).join('')}</div><div id="${uid}-practice" class="cb-task" aria-live="polite"><p class="cb-label">${steps[step][1]}</p><p>${escape(place.task[steps[step][0]])}</p></div></div><div class="cb-blackbook"><label for="${uid}-note">Tvůj Blackbook / pozorování a vlastní výstup</label><textarea id="${uid}-note" data-cb-note rows="4" maxlength="20000" placeholder="Co jsi opravdu zaznamenal? Co jsi vytvořil a co bys příště změnil?"></textarea><div class="cb-save-row"><button type="button" data-cb-save>Uložit do Blackbooku ↓</button><p data-cb-status role="status">Poznámky zůstávají v tomto prohlížeči. Export najdeš v zápisníku nahoře.</p></div></div><div class="cb-quest-links"><button type="button" data-cb-open="${escape(place.id)}">Otevřít v atlasu ↗</button><a href="/expeditions/${expedition}/">Navazující expedice ↗</a><a href="/play/">SELFMADE / vlastní dílna ↗</a></div><details class="cb-sources"><summary>Zdroje a podmínky návštěvy <span>${escape(place.checkedAt)}</span></summary><p>Kontrola zdrojů: ${escape(place.checkedAt)}. Program a vstupní podmínky ověř u provozovatele před cestou. Nejde o partnerství ani rezervaci.</p><ul>${sourceLinks}</ul></details></article></div>`;
  const noteInput=host.querySelector('[data-cb-note]');if(noteInput)noteInput.value=typeof note==='string'?note:'';
  refreshMotion();
 }
 function choose(id,{focus=false}={}){if(!items.some(place=>place.id===id))return;capture();selected=id;step=0;render();if(focus)host.querySelector(`#${uid}-title`)?.focus({preventScroll:true});}
 function onClick(event){const button=event.target.closest('button');if(!button||!host.contains(button))return;
  if(button.hasAttribute('data-cb-place'))choose(button.dataset.cbPlace);
  else if(button.hasAttribute('data-cb-filter')){capture();filter=button.dataset.cbFilter;const available=filtered();if(!available.some(place=>place.id===selected))selected=available[0]?.id||items[0].id;step=0;render();onFilter(filter);}
  else if(button.hasAttribute('data-cb-step')){capture();step=Math.max(0,Math.min(steps.length-1,Number(button.dataset.cbStep)||0));render();host.querySelector(`[data-cb-step="${step}"]`)?.focus({preventScroll:true});}
  else if(button.hasAttribute('data-cb-prev')||button.hasAttribute('data-cb-next')){const available=filtered(),index=available.findIndex(place=>place.id===selected),direction=button.hasAttribute('data-cb-next')?1:-1;choose(available[(index+direction+available.length)%available.length].id,{focus:true});}
  else if(button.hasAttribute('data-cb-field')){capture();field=!field;render();host.querySelector('[data-cb-field]')?.focus({preventScroll:true});}
  else if(button.hasAttribute('data-cb-open'))onOpen(button.dataset.cbOpen);
  else if(button.hasAttribute('data-cb-save')){capture();const text=drafts.get(selected)?.trim()||'',status=host.querySelector('[data-cb-status]');if(!text){status.textContent='Nejdřív napiš vlastní pozorování nebo výstup.';return;}const notes={...storedNotes(),[selected]:text};let okay=false;try{okay=write('atlas-observations',notes)!==false;}catch{}const message=okay?'Uloženo do Blackbooku v tomto prohlížeči.':'Trvalé uložení se nezdařilo. Text zůstává pro tuto návštěvu; zkopíruj jej nebo exportuj zápisník.';status.textContent=message;status.classList.toggle('cb-save-error',!okay);notify(message);}
 }
 listen(host,'click',onClick);listen(host,'input',event=>{if(event.target.matches('[data-cb-note]')){drafts.set(selected,event.target.value);const status=host.querySelector('[data-cb-status]');status.textContent='Neuložená úprava. Ulož ji do Blackbooku.';status.classList.remove('cb-save-error');}});
 listen(host,'pointermove',event=>{if(event.pointerType==='touch'||!allowed())return;const stage=event.target.closest('.cb-symbol-stage');if(!stage)return;const rect=stage.getBoundingClientRect();if(!rect.width||!rect.height)return;const x=Math.max(-1,Math.min(1,(event.clientX-rect.left)/rect.width*2-1)),y=Math.max(-1,Math.min(1,(event.clientY-rect.top)/rect.height*2-1));if(raf)win.cancelAnimationFrame(raf);raf=win.requestAnimationFrame(()=>{raf=0;host.style.setProperty('--cb-x',`${(x*10).toFixed(2)}px`);host.style.setProperty('--cb-y',`${(y*7).toFixed(2)}px`);});});
 listen(host,'pointerleave',()=>{if(raf)win.cancelAnimationFrame(raf);raf=0;host.style.removeProperty('--cb-x');host.style.removeProperty('--cb-y');});
 listen(doc,'visibilitychange',refreshMotion);if(reduced?.addEventListener)listen(reduced,'change',refreshMotion);
 let io,mo;
 if(win.IntersectionObserver){io=new win.IntersectionObserver(entries=>{for(const entry of entries)if(entry.target===host)visible=entry.isIntersecting;refreshMotion();},{threshold:.03});io.observe(host);}
 if(win.MutationObserver){mo=new win.MutationObserver(records=>{if(records.some(record=>(record.target===doc.documentElement&&['data-motion','data-selfmade-motion'].includes(record.attributeName))||(record.target===doc.body&&record.attributeName==='class')||(record.target.tagName==='DIALOG'&&record.attributeName==='open')||(record.type==='childList'&&[...record.addedNodes,...record.removedNodes].some(node=>node.nodeType===1&&(node.matches?.('dialog')||node.querySelector?.('dialog'))))))refreshMotion();});mo.observe(doc.documentElement,{attributes:true,attributeFilter:['data-motion','data-selfmade-motion']});mo.observe(doc.body,{attributes:true,subtree:true,childList:true,attributeFilter:['open','class']});}
 render();
 return {select(id){if(items.some(place=>place.id===id)){filter='all';choose(id);}},getState:()=>({selected,filter,step,field,count:items.length,playing:allowed()}),destroy(){if(disposed)return;disposed=true;io?.disconnect();mo?.disconnect();listeners.forEach(remove=>remove());if(raf)win.cancelAnimationFrame(raf);host.classList.remove('culture-board','cb-field','cb-animating');host.style.removeProperty('--cb-x');host.style.removeProperty('--cb-y');host.replaceChildren();drafts.clear();}};
}
